using namespace moon;
namespace {
void check(bool value,const char* why){if(!value)throw std::runtime_error(why);}
std::uint32_t hash(const std::vector<Pixel>& pixels){std::uint32_t h=2166136261u;for(auto p:pixels)for(unsigned shift=0;shift<32;shift+=8){h^=(p>>shift)&255;h*=16777619u;}return h;}
std::vector<Pixel> pattern(int w,int h){std::vector<Pixel> p(std::size_t(w)*h);for(int y=0;y<h;++y)for(int x=0;x<w;++x){const unsigned a[]{0,1,127,255};p[std::size_t(y)*w+x]=((x*17+y*3)&255)|(((x*5+y*29)&255)<<8)|(((x*11+y*7)&255)<<16)|(a[(x+y)%4]<<24);}return p;}
void reopen(Document& d,const std::filesystem::path& path){const auto expected=d.pixels();const auto name=d.name();project::saveDocumentAtomic(d,path);std::ifstream in(path,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto result=std::make_unique<Document>(project::createEditableDocument(project::prepareEditableImport(project::readProjectManifest(bytes))));check(result->width()==d.width()&&result->height()==d.height()&&result->name()==name&&result->pixels()==expected&&!result->dirty()&&!result->canUndo(),"Large creation real save/reopen");}
void run(const LargeCreationOracle& oracle,const std::filesystem::path& root){const int w=oracle.width,h=oracle.height;
 const auto prefix=std::to_string(w)+"x"+std::to_string(h);auto fresh=std::make_unique<Document>(Document::withBuiltinPalette(w,h,U"Large creation"));
 check(fresh->width()==w&&fresh->height()==h&&fresh->palette().entries.size()==32&&!fresh->dirty()&&!fresh->canUndo()&&fresh->historySize()==0&&fresh->sourceFilePath().empty()&&!fresh->sourceArchive(),"Large new document baseline");
 fresh->beginStroke({w-1,h-1},0xff2040c0);fresh->commitStroke();check(fresh->pixels().back()==0xff2040c0,"Large new edge edit");fresh->undo();check(fresh->pixels().back()==0,"Large new edge undo");fresh->redo();reopen(*fresh,root/(prefix+"-new.moonsprite"));fresh.reset();
 SelectionClipboard source;source.width=w;source.height=h;source.originX=-40;source.originY=88;source.pixels=pattern(w,h);source.mask.resize(source.pixels.size());for(std::size_t i=0;i<source.mask.size();++i)source.mask[i]=i%3;
 auto expected=source.pixels;for(std::size_t i=0;i<expected.size();++i)if(source.mask[i]!=1)expected[i]=0;
 auto pasted=std::make_unique<Document>(Document::fromClipboardRaster(source));check(pasted->pixels()==expected&&pasted->dirty()&&!pasted->canUndo()&&pasted->palette().entries.size()==2&&!pasted->sourceArchive()&&!pasted->selection()&&pasted->sourceFilePath().empty(),"Large paste mask/defaults");check(hash(pasted->pixels())==oracle.masked,"Actual legacy masked clipboard full pixel hash");reopen(*pasted,root/(prefix+"-paste.moonsprite"));pasted.reset();
 for(int bits:{24,32}){clip::image_spec spec;spec.width=w;spec.height=h;spec.bits_per_pixel=bits;spec.bytes_per_row=((w*(bits/8)+3)/4)*4;spec.red_mask=255;spec.green_mask=255<<8;spec.blue_mask=255<<16;spec.alpha_mask=bits==32?0xff000000:0;spec.green_shift=8;spec.blue_shift=16;spec.alpha_shift=24;clip::image image(spec);std::memset(image.data(),0xcd,spec.required_data_size());for(int y=0;y<h;++y)for(int x=0;x<w;++x){auto p=source.pixels[std::size_t(y)*w+x];std::memcpy(image.data()+std::size_t(y)*spec.bytes_per_row+x*(bits/8),&p,bits/8);}auto decoded=PixelClipboard::decodeSystemImage(image,true);for(std::size_t i=0;i<source.pixels.size();++i){check(decoded.pixels[i]==(bits==32?source.pixels[i]:source.pixels[i]|0xff000000),"Native clipboard padded row/channel conversion");check(decoded.mask[i]==(bits==24||source.pixels[i]>>24?1:0),"Native clipboard alpha mask");}auto result=std::make_unique<Document>(Document::fromClipboardRaster(decoded));for(std::size_t i=0;i<decoded.pixels.size();++i)check(result->pixels()[i]==(decoded.mask[i]?decoded.pixels[i]:0),"Native clipboard conversion to new document");check(hash(result->pixels())==(bits==24?oracle.os24:oracle.os32),"Actual legacy OS clipboard full pixel hash");}
 auto sheetSource=std::make_unique<Document>(Document::fromImage(w,h,source.pixels,U"Sheet source"));sheetSource->addLinkedFrame();const auto history=sheetSource->historySize(),revision=sheetSource->revision();const auto pixels=sheetSource->pixels();
 for(auto layout:{SheetLayout::Horizontal,SheetLayout::Vertical}){if((layout==SheetLayout::Horizontal&&w>16384)||(layout==SheetLayout::Vertical&&h>16384))continue;SpriteSheetOptions options;options.layout=layout;auto raster=buildSpriteSheetImage(*sheetSource,options);auto sheet=std::make_unique<Document>(createSpriteSheetDocument(*sheetSource,options));check(sheet->width()==raster.width&&sheet->height()==raster.height&&sheet->pixels()==raster.pixels&&sheet->dirty()&&!sheet->canUndo()&&sheet->palette().entries.size()==2&&sheet->layer().name==U"精灵表"&&sheet->name()==U"Sheet source - 精灵表"&&!sheet->sourceArchive()&&sheet->sourceFilePath().empty(),"Large sheet output semantics");if(hash(sheet->pixels())!=(layout==SheetLayout::Horizontal?oracle.horizontal:oracle.vertical))throw std::runtime_error("Actual legacy sheet hash "+prefix+" layout="+std::to_string(int(layout))+" actual="+std::to_string(hash(sheet->pixels()))+" expected="+std::to_string(layout==SheetLayout::Horizontal?oracle.horizontal:oracle.vertical));reopen(*sheet,root/(prefix+(layout==SheetLayout::Horizontal?"-horizontal.moonsprite":"-vertical.moonsprite")));check(sheetSource->historySize()==history&&sheetSource->revision()==revision&&sheetSource->pixels()==pixels,"Sheet changed source");}
}
void bounds(){
 for(const auto size:{std::pair<unsigned long,unsigned long>{32769,1},{1,32769},{4096,4097},{0,1},{1,0}}){clip::image_spec spec;spec.width=size.first;spec.height=size.second;spec.bits_per_pixel=32;spec.bytes_per_row=spec.width*4;bool failed=false;try{PixelClipboard::validateSystemImage(spec,true);}catch(const PixelClipboard::ImageNotAdmitted&){failed=true;}check(failed,"Clipboard admission must reject before get_image");}
 clip::image_spec valid;valid.width=4096;valid.height=4096;valid.bits_per_pixel=32;valid.bytes_per_row=16384;PixelClipboard::validateSystemImage(valid,true);
 for(int variant=0;variant<4;++variant){auto bad=valid;if(variant==0)bad.bytes_per_row=1;if(variant==1)bad.bits_per_pixel=16;if(variant==2)bad.red_shift=32;if(variant==3)bad.bytes_per_row=0xffffffff;bool failed=false;try{PixelClipboard::validateSystemImage(bad,true);}catch(const PixelClipboard::ImageNotAdmitted&){failed=true;}check(failed,"Clipboard row/bit-depth/shift preflight");}
 auto longImage=valid;longImage.width=8193;longImage.height=1;longImage.bytes_per_row=8193*4;PixelClipboard::validateSystemImage(longImage,true);bool selectionRejected=false;try{PixelClipboard::validateSystemImage(longImage,false);}catch(const std::length_error&){selectionRejected=true;}check(selectionRejected,"Ordinary selection/reference dimension admission changed");
 for(const auto size:{std::pair<int,int>{32769,1},{1,32769},{8192,8193},{0,1}}){SelectionClipboard source;source.width=size.first;source.height=size.second;bool failed=false;try{Document::fromClipboardRaster(source);}catch(const std::length_error&){failed=true;}check(failed,"Clipboard document header admission");failed=false;try{Document::fromSpriteSheetRaster(size.first,size.second,{},U"bad");}catch(const std::length_error&){failed=true;}check(failed,"Sheet document header admission");}
 auto source=std::make_unique<Document>(16385,1);source->addFrame();const auto identity=source->identity(),history=source->historySize();bool failed=false;try{createSpriteSheetDocument(*source,{});}catch(const std::length_error&){failed=true;}check(failed&&source->identity()==identity&&source->historySize()==history&&source->width()==16385,"Overside sheet failure/source preservation");
}
}
int wmain(int argc,wchar_t** argv){try{const auto root=std::filesystem::path(argc>1?argv[1]:L"large-creation-test-owned")/(std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));std::filesystem::create_directories(root);for(const auto& oracle:largeCreationOracle)run(oracle,root);bounds();std::ofstream(root/"result.txt")<<"Five large dimension pairs: new/paste/24+32bit padded native clipboard conversion/sheet outputs and real save-reopen; pre-allocation dimensions/16Mi-pixel budget/source preservation passed. System clipboard untouched.\n";std::cout<<root.u8string()<<" passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
